function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // sun
  ctx.fillStyle = 'yellow';
  ctx.beginPath();
  ctx.arc(W/2, H/2, 50, 0, 2 * Math.PI);
  ctx.fill();

  // earth
  ctx.fillStyle = 'green';
  ctx.beginPath();
  ctx.arc(W/2, H/2, 100, 0, 2 * Math.PI);
  ctx.lineWidth = 3;
  ctx.strokeStyle = 'black';
  ctx.stroke();

  // seasonal foods
  ctx.fillStyle = 'red';
  ctx.beginPath();
  ctx.arc(W/2 + 80 * Math.cos(t), H/2 + 80 * Math.sin(t), 20, 0, 2 * Math.PI);
  ctx.fill();

  ctx.fillStyle = 'orange';
  ctx.beginPath();
  ctx.arc(W/2 + 80 * Math.cos(t + Math.PI/2), H/2 + 80 * Math.sin(t + Math.PI/2), 20, 0, 2 * Math.PI);
  ctx.fill();

  ctx.fillStyle = 'blue';
  ctx.beginPath();
  ctx.arc(W/2 + 80 * Math.cos(t + Math.PI), H/2 + 80 * Math.sin(t + Math.PI), 20, 0, 2 * Math.PI);
  ctx.fill();

  ctx.fillStyle = 'purple';
  ctx.beginPath();
  ctx.arc(W/2 + 80 * Math.cos(t + 3*Math.PI/2), H/2 + 80 * Math.sin(t + 3*Math.PI/2), 20, 0, 2 * Math.PI);
  ctx.fill();

  // stick figure
  ctx.lineWidth = 3;
  ctx.strokeStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2, H/2 + 120, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 140);
  ctx.lineTo(W/2, H/2 + 200);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 160);
  ctx.lineTo(W/2 - 30, H/2 + 180);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 160);
  ctx.lineTo(W/2 + 30, H/2 + 180);
  ctx.stroke();

  ctx.restore();
}
